namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }
    public int MaxSentences { get; set; } = 3;
}

public class SummarizeResponse
{
    public required string Summary { get; set; }
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    string Summarize(string documentText, int maxSentences);
}

public class DocumentSummaryService : IDocumentSummaryService
{
    public string Summarize(string documentText, int maxSentences)
    {
        if (string.IsNullOrWhiteSpace(documentText))
            return string.Empty;

        // Split text into sentences using common delimiters
        var sentences = documentText
            .Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(s => s.Length > 0)
            .ToList();

        if (sentences.Count == 0)
            return string.Empty;

        // Score sentences by word frequency (extractive summarization)
        var wordFrequencies = GetWordFrequencies(documentText);
        var scoredSentences = sentences
            .Select((sentence, index) => new { Sentence = sentence, Index = index, Score = ScoreSentence(sentence, wordFrequencies) })
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index) // Preserve original order
            .Select(s => s.Sentence.Trim());

        return string.Join(". ", scoredSentences) + ".";
    }

    private static Dictionary<string, int> GetWordFrequencies(string text)
    {
        var words = text
            .ToLowerInvariant()
            .Split([' ', '\t', '\n', '\r', ',', '.', '!', '?', ';', ':', '"', '\'', '(', ')'],
                   StringSplitOptions.RemoveEmptyEntries);

        var frequencies = new Dictionary<string, int>();
        foreach (var word in words)
        {
            if (word.Length <= 3) continue; // Skip short/common words
            frequencies[word] = frequencies.GetValueOrDefault(word) + 1;
        }
        return frequencies;
    }

    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
    {
        var words = sentence.ToLowerInvariant().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (words.Length == 0) return 0;

        var score = words.Sum(w => wordFrequencies.GetValueOrDefault(w));
        return (double)score / words.Length;
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly IDocumentSummaryService _summaryService;

    public SummarizeController(IDocumentSummaryService summaryService)
    {
        _summaryService = summaryService;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest("DocumentText is required.");

        var summary = _summaryService.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

